'use client';
import { useEffect, useRef, useState, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { Spin, Swap, Think, Tip, useGrow } from '../lib/motion';
import '../designme.css';
import './plan-review.css';

export interface PlanReviewStep {
  id: string;
  text: string;
  /** Left out of the plan; it stays in the list, struck through */
  skipped?: boolean;
  /** Marks a step the person rewrote */
  edited?: boolean;
  /** run while the agent works on it, retry while it waits out a problem (a rate limit, a timeout), done once it has */
  state?: 'run' | 'retry' | 'done';
  /** The line the step reports, under it: what it found, or what it waits on. Opens and crossfades when it changes */
  detail?: string;
}

export type PlanPhase = 'review' | 'running' | 'done';

export interface PlanReviewProps {
  /** Like "Plan: redesign the pricing page" */
  title: string;
  /** The steps. Leave `steps` out to let the person edit, skip and add steps on their own */
  steps?: PlanReviewStep[];
  defaultSteps?: PlanReviewStep[];
  onStepsChange?: (steps: PlanReviewStep[]) => void;
  /** review (steps can be edited), running (the agent works through them) or done */
  phase?: PlanPhase;
  /** The line under the title. Defaults to roughly how long the steps left in take (the list shows how many there are) */
  status?: string;
  /** The quiet line in the footer. Defaults to a hint for each phase */
  note?: string;
  /** Quiet text at the end of the header, like an elapsed time "0:04" */
  meta?: ReactNode;
  onApprove?: () => void;
  onRequestChanges?: () => void;
  onStop?: () => void;
  onSeeChanges?: () => void;
  /** Draws its own container (the default, as on designme.dev). Set true to sit it flat in a chat thread */
  bare?: boolean;
  className?: string;
}

// the foot never repeats the head: while the plan runs it has only Stop (owner, 18 Nov)
const NOTE: Record<PlanPhase, string> = { review: 'Click a step to edit it', running: '', done: '' };
let added = 0;

/** A plan the agent proposes before it starts: edit a step, skip it, add one, then approve. */
export function PlanReview({ title, steps, defaultSteps = [], onStepsChange, phase = 'review', status, note, meta, onApprove, onRequestChanges, onStop, onSeeChanges, bare = false, className }: PlanReviewProps) {
  const [list, setList] = useControllable(steps, defaultSteps, onStepsChange);
  const live = useRef(list);
  useEffect(() => { live.current = list; });
  // each step remembers the words it came with, so "edited" shows only when they really changed
  const original = useRef(new Map<string, string>());
  list.forEach(s => { if (!original.current.has(s.id)) original.current.set(s.id, s.text); });
  // the rows stagger in once; after that the entrance comes off so a skipped step can fade
  const [entered, setEntered] = useState<Set<string>>(() => new Set());
  const first = useRef(new Set(list.map(s => s.id)));
  const focusId = useRef<string | null>(null);
  const textRefs = useRef(new Map<string, HTMLSpanElement>());

  useEffect(() => {
    const id = focusId.current, el = id && textRefs.current.get(id); if (!el) return;
    focusId.current = null; el.focus(); getSelection()?.selectAllChildren(el);
  });

  const update = (id: string, change: Partial<PlanReviewStep>) => setList(live.current.map(s => s.id === id ? { ...s, ...change } : s));
  const included = list.filter(s => !s.skipped);
  const editable = phase === 'review';
  let n = 0;
  // the panel grows with the plan (owner, 17 Nov): its height eases to its content, nothing kept for the final state
  const [growRef, growIn] = useGrow();

  return (
    <div data-dm="" ref={growRef} className={cx('dm-plx', 'dm-growing', !bare && 'dm-panel', className)}>
      <div className="dm-grow" ref={growIn}>
      <div className="dm-plx-h">
        <Think on={phase === 'running'} className="dm-plx-mk" />
        <div className="dm-plx-ht"><b>{title}</b><Swap className={cx('dm-muted dm-plx-st', phase === 'running' && 'dm-shim')}>{status ?? `About ${Math.max(1, Math.round(included.length * .8))} min`}</Swap></div>
        {meta !== undefined && <span className="dm-plx-tm dm-num">{meta}</span>}
      </div>
      <ol className="dm-plx-list">
        {list.map((s, i) => {
          const num = s.skipped ? '–' : String(++n);
          const entering = !entered.has(s.id);
          return (
            <li key={s.id} className={cx('dm-plx-s', entering && 'dm-enter', s.skipped && 'dm-off', s.state && 'dm-' + s.state, s.edited && 'dm-edited')}
              style={entering ? { animationDelay: (first.current.has(s.id) ? 100 + i * 60 : 0) + 'ms' } : undefined}
              onAnimationEnd={e => { if (e.target === e.currentTarget) setEntered(prev => new Set(prev).add(s.id)); }}>
              <span className="dm-n">{s.state === 'done' ? <Icon name="check" size="xs" /> : s.state === 'run' ? <Spin /> : s.state === 'retry' ? <Icon name="clock" size="xs" /> : num}</span>
              <span className="dm-b">
              <span className={cx('dm-t', s.state === 'run' && 'dm-shim')} ref={el => { if (el) textRefs.current.set(s.id, el); else textRefs.current.delete(s.id); }}
                contentEditable={editable} suppressContentEditableWarning spellCheck={false} role={editable ? 'textbox' : undefined} aria-label={editable ? `Step ${num}` : undefined}
                onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); e.currentTarget.blur(); } }}
                onBlur={e => { const text = e.currentTarget.textContent ?? ''; if (text !== s.text) update(s.id, { text, edited: text.trim() !== original.current.get(s.id) }); }}>
                {s.text}
              </span>
              <span className={cx('dm-d', s.detail && 'dm-on', s.state === 'retry' && 'dm-warn')}><Swap className={s.state === 'run' && s.detail ? 'dm-shim' : undefined}>{s.detail ?? ''}</Swap></span>
              </span>
              {editable && (
                <Tip label={s.skipped ? 'Include step' : 'Skip step'}>
                  <button type="button" className="dm-ib dm-plx-x" aria-label={s.skipped ? 'Include step' : 'Skip step'} onClick={() => update(s.id, { skipped: !s.skipped })}>
                    <Icon name={s.skipped ? 'undo' : 'x'} size="xs" />
                  </button>
                </Tip>
              )}
            </li>
          );
        })}
      </ol>
      {editable && (
        <button type="button" className="dm-plx-add" onClick={() => { const id = `new-${++added}`; focusId.current = id; setList([...live.current, { id, text: 'New step' }]); }}>
          <Icon name="plus" size="xs" />Add a step
        </button>
      )}
      <div className="dm-plx-f" key={phase}>
        <Swap className="dm-muted dm-plx-n">{note ?? NOTE[phase]}</Swap>
        {phase === 'review' && <>
          <button type="button" className="dm-pill dm-ghost dm-sm dm-plx-chg" onClick={onRequestChanges}>Ask for changes</button>
          <button type="button" className="dm-pill dm-primary dm-sm dm-plx-go" onClick={onApprove}>Approve plan</button>
        </>}
        {phase === 'running' && <button type="button" className="dm-pill dm-ghost dm-sm dm-plx-stop dm-enter" style={{ animationDelay: '50ms' }} onClick={onStop}><Icon name="stop" size="xs" />Stop</button>}
        {phase === 'done' && <button type="button" className="dm-pill dm-soft dm-sm dm-enter" onClick={onSeeChanges}><Icon name="eye" size="xs" />See changes</button>}
      </div>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Plan review ---------- */
/* the plan the agent posts in the chat: no container; with .panel it becomes a card */
.dm-plx{padding:14px 0;display:flex;flex-direction:column;gap:10px;--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
.dm-plx.dm-panel{padding:var(--dm-s-4)}
.dm-plx-h{display:flex;align-items:center;gap:10px}
/* the header's mark sits in the steps' 32px number column, centred */
.dm-plx-mk{color:var(--dm-accent-fg,var(--dm-accent));margin-inline:9px}
.dm-plx-ht{display:flex;flex-direction:column;min-width:0}
.dm-plx-ht b{font-weight:500;font-size:13.5px}
.dm-plx-st{font-size:12.5px}
/* every part on shared columns, in every style (owner, 18 Nov): the header's mark and each step's number are centred in one
   32px column, so the steps' words start where the title's do; a step's hover fill spans the content and no wider */
.dm-plx-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;counter-reset:s}
.dm-plx-s{display:flex;align-items:flex-start;gap:10px;padding:7px 4px 7px 0;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));font-size:13px;transition:background .25s,opacity .35s;position:relative}
@media (hover:hover) and (pointer:fine){.dm-plx-s:hover{background:var(--dm-row)}}
.dm-plx-s .dm-n{width:20px;height:20px;margin-inline:6px;border-radius:50%;background:var(--dm-chip);display:grid;place-items:center;font-size:11px;font-variant-numeric:tabular-nums;color:var(--dm-muted);flex:none;transition:background .35s,color .35s}
@media (hover:hover) and (pointer:fine){.dm-plx-s:hover .dm-n{background:var(--dm-surface)}}
.dm-plx-s .dm-b{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-plx-s .dm-t{min-width:0;outline:0;border-radius:var(--dm-r-tiny,5px);padding:1px 3px;margin:0 -3px;line-height:1.5}
/* the line a step reports: it opens under the step, in the step's colour while it waits on something */
.dm-plx-s .dm-d{font-size:12px;color:var(--dm-muted);display:grid;grid-template-rows:0fr;transition:grid-template-rows .32s var(--dm-ease)}
.dm-plx-s .dm-d.dm-on{grid-template-rows:1fr}
.dm-plx-s .dm-d>span{overflow:hidden;min-height:0}
/* a running step's note ("Retrying") has the loader's sweep; the note it replaces fades out in its own colour, unswept */
.dm-plx-s .dm-d>.dm-shim.dm-out{color:inherit;background:none;animation:none}
.dm-plx-s .dm-d.dm-warn{color:var(--dm-warn)}
.dm-plx-tm{margin-left:auto;font-size:12px;color:var(--dm-muted)}
.dm-plx-tm:empty{display:none}
.dm-plx-s .dm-n .dm-spin{width:10px;height:10px}
.dm-plx-s .dm-t:focus{background:var(--dm-surface);box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.dm-plx-s .dm-ib{width:24px;height:24px;opacity:0;transition:opacity .2s}
.dm-plx-s .dm-ib:focus-visible{opacity:1}
@media (hover:hover) and (pointer:fine){.dm-plx-s:hover .dm-ib{opacity:1}}
.dm-plx-s.dm-off{opacity:.45}
.dm-plx-s.dm-off .dm-t{text-decoration:line-through}
.dm-plx-s.dm-run .dm-n{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
/* a finished step is neutral with the green tick, no green fill (owner, 18 Nov) */
.dm-plx-s.dm-done .dm-n{background:var(--dm-chip);color:var(--dm-ok)}
.dm-plx-s.dm-retry .dm-n{background:var(--dm-warn-bg);color:var(--dm-warn)}
.dm-plx-s.dm-edited .dm-t::after{content:"edited";margin-left:6px;font-size:11px;color:var(--dm-accent-fg,var(--dm-accent))}
.dm-plx-add{display:flex;align-items:center;gap:10px;font-size:12.5px;color:var(--dm-fg2);padding:6px 0;align-self:stretch;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)))}
.dm-plx-add .dm-i{margin-inline:10px}
@media (hover:hover) and (pointer:fine){.dm-plx-add:hover{color:var(--dm-fg);background:var(--dm-row)}}
/* the footer's buttons end on the content's right edge, also on a phone, where the note beside them is left out */
.dm-plx-f{display:flex;align-items:center;justify-content:flex-end;gap:6px}
/* the footer sits under a hairline in Soft and Blueprint, in every state (owner, 21 Nov: "shouldn't there be a divider line
   there?"), 16px under the last step and 16px over its buttons, as the card's own edges are; Clean's is a foot strip (below) */
.dm-plx-f{margin-top:6px;padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
/* Stop, the footer's last control, has its word on the content's right edge and its hover box reaching out round it */
.dm-plx-f .dm-plx-stop:last-child{margin-right:-11px}
.dm-plx-n{flex:1;font-size:12px;min-width:0}
@media (max-width:480px){.dm-plx-n{display:none}}
/* Clean (lead and owner, 18 Nov): a card with the plan and an off-white foot strip, everything on shared columns. Its
   content sits 16px in from every edge: the header's mark sits in a 32px neutral tile, and each step's number circle is
   centred in that same 32px column, as Add a step's plus is, so every step's words start where the title's do. A step's
   hover fill spans the content, from the tile's left edge to the content's right edge, never wider; the skip button is
   centred in a 32px column at its end. The foot strip's hint starts at the content's left edge, and its buttons sit 8px from
   the card's edges, the 28px buttons' 14px ends and 8px making the card's 22px corner. A queued step is a hairline circle with its number, the step in hand a spinner ring in the accent (white in dark mode), one
   waiting out a problem an orange ring with its clock, a finished one a neutral circle with a green ring and tick (no green
   fill, as a finished row has none): two hues, and only on
   steps that run or have run. Each step's line comes in only once the agent has done it (or is waiting on something), and
   the header sums the run up only once it is over. "edited" is quiet grey text */
